<?php
require 'auth.php';require_login();require 'db.php';require 'layout.php';
$counts=[];
foreach(['animals'=>'SELECT COUNT(*) c FROM animal','reports'=>'SELECT COUNT(*) c FROM reports','adoptions'=>'SELECT COUNT(*) c FROM adoption_request','donations'=>'SELECT COALESCE(SUM(amount),0) c FROM donations WHERE status="received"'] as $k=>$q){$counts[$k]=$conn->query($q)->fetch_assoc()['c'];}
$recent=$conn->query('SELECT animal_id,name,species,status,photo FROM animal ORDER BY animal_id DESC LIMIT 4');
page_top('Dashboard');
?><section class="hero"><div><h1>Hello, <?=h($_SESSION['full_name'])?>! 🐾</h1><p>Manage rescue cases, animals, adoptions, feeding, treatments and donations from one place.</p><p class="muted">Role: <?=h($_SESSION['role']==='volunteer'?'Volunteer':'General User')?></p></div><img src="assets/cat-logo.png" alt="cat"></section><div class="stats"><div class="stat"><span>Animals</span><strong><?=$counts['animals']?></strong></div><div class="stat"><span>Reports</span><strong><?=$counts['reports']?></strong></div><div class="stat"><span>Adoption requests</span><strong><?=$counts['adoptions']?></strong></div><div class="stat"><span>Donations received</span><strong>৳<?=number_format((float)$counts['donations'],2)?></strong></div></div><div class="section-head"><h2>Recently registered animals</h2><a class="btn secondary" href="animals.php">View all</a></div><div class="grid"><?php while($a=$recent->fetch_assoc()):?><article class="card animal-card"><img src="<?=h($a['photo']?'uploads/'.$a['photo']:'assets/cat-logo.png')?>" alt="animal"><h3><?=h($a['name'])?></h3><p><?=h($a['species'])?></p><span class="tag"><?=h(str_replace('_',' ',$a['status']))?></span></article><?php endwhile;?></div><?php page_bottom(); ?>
